/// Settings for systematic choices. `Aramaic::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Aramaic {
    pub options: Options,
}

impl Aramaic {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, state: State, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (state, number,) {
            (State::Absolute, Number::Singular,) => Some(0),
            (State::Absolute, Number::Plural,) => Some(1),
            (State::Construct, Number::Singular,) => Some(2),
            (State::Construct, Number::Plural,) => Some(3),
            (State::Emphatic, Number::Singular,) => Some(4),
            (State::Emphatic, Number::Plural,) => Some(5),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, state: State, number: Number) -> String {
        best(self.noun_scored(word, state, number), word)
    }

    /// Scored gender of a noun.
    pub fn noun_gender(&self, word: &str) -> Scored<Gender> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Gender::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adj form.
    pub fn adj_scored(&self, word: &str, state: State, gender: Gender, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (state, gender, number,) {
            (State::Absolute, Gender::Masculine, Number::Singular,) => Some(0),
            (State::Absolute, Gender::Masculine, Number::Plural,) => Some(1),
            (State::Absolute, Gender::Feminine, Number::Singular,) => Some(2),
            (State::Absolute, Gender::Feminine, Number::Plural,) => Some(3),
            (State::Construct, Gender::Masculine, Number::Singular,) => Some(4),
            (State::Construct, Gender::Masculine, Number::Plural,) => Some(5),
            (State::Construct, Gender::Feminine, Number::Singular,) => Some(6),
            (State::Construct, Gender::Feminine, Number::Plural,) => Some(7),
            (State::Emphatic, Gender::Masculine, Number::Singular,) => Some(8),
            (State::Emphatic, Gender::Masculine, Number::Plural,) => Some(9),
            (State::Emphatic, Gender::Feminine, Number::Singular,) => Some(10),
            (State::Emphatic, Gender::Feminine, Number::Plural,) => Some(11),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form. The best candidate; the word itself if nothing is known.
    pub fn adj(&self, word: &str, state: State, gender: Gender, number: Number) -> String {
        best(self.adj_scored(word, state, gender, number), word)
    }

    /// Dictionary spelling of a adj (with stress marks where the data has them).
    pub fn adj_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

    /// A verb form.
    pub fn verb_scored(&self, word: &str, tense: Tense, person: Person) -> Scored<String> {
        let cell: Option<u32> = match (tense, person,) {
            (Tense::Past, Person::FirstSingular,) => Some(0),
            (Tense::Past, Person::SecondMasculineSingular,) => Some(1),
            (Tense::Past, Person::SecondFeminineSingular,) => Some(2),
            (Tense::Past, Person::ThirdMasculineSingular,) => Some(3),
            (Tense::Past, Person::ThirdFeminineSingular,) => Some(4),
            (Tense::Past, Person::FirstPlural,) => Some(5),
            (Tense::Past, Person::SecondMasculinePlural,) => Some(6),
            (Tense::Past, Person::SecondFemininePlural,) => Some(7),
            (Tense::Past, Person::ThirdMasculinePlural,) => Some(8),
            (Tense::Past, Person::ThirdFemininePlural,) => Some(9),
            (Tense::Future, Person::FirstSingular,) => Some(10),
            (Tense::Future, Person::SecondMasculineSingular,) => Some(11),
            (Tense::Future, Person::SecondFeminineSingular,) => Some(12),
            (Tense::Future, Person::ThirdMasculineSingular,) => Some(13),
            (Tense::Future, Person::ThirdFeminineSingular,) => Some(14),
            (Tense::Future, Person::FirstPlural,) => Some(15),
            (Tense::Future, Person::SecondMasculinePlural,) => Some(16),
            (Tense::Future, Person::SecondFemininePlural,) => Some(17),
            (Tense::Future, Person::ThirdMasculinePlural,) => Some(18),
            (Tense::Future, Person::ThirdFemininePlural,) => Some(19),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(2, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form. The best candidate; the word itself if nothing is known.
    pub fn verb(&self, word: &str, tense: Tense, person: Person) -> String {
        best(self.verb_scored(word, tense, person), word)
    }

    /// A verb form (imperative).
    pub fn verb_imperative_scored(&self, word: &str, imperative: Imperative) -> Scored<String> {
        let cell: Option<u32> = match (imperative,) {
            (Imperative::MasculineSingular,) => Some(20),
            (Imperative::FeminineSingular,) => Some(21),
            (Imperative::MasculinePlural,) => Some(22),
            (Imperative::FemininePlural,) => Some(23),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(2, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form (imperative). The best candidate; the word itself if nothing is known.
    pub fn verb_imperative(&self, word: &str, imperative: Imperative) -> String {
        best(self.verb_imperative_scored(word, imperative), word)
    }

    /// A verb form (participle).
    pub fn verb_participle_scored(&self, word: &str, imperative: Imperative) -> Scored<String> {
        let cell: Option<u32> = match (imperative,) {
            (Imperative::MasculineSingular,) => Some(24),
            (Imperative::FeminineSingular,) => Some(25),
            (Imperative::MasculinePlural,) => Some(26),
            (Imperative::FemininePlural,) => Some(27),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(2, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A verb form (participle). The best candidate; the word itself if nothing is known.
    pub fn verb_participle(&self, word: &str, imperative: Imperative) -> String {
        best(self.verb_participle_scored(word, imperative), word)
    }

    /// Dictionary spelling of a verb (with stress marks where the data has them).
    pub fn verb_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(2, word)).unwrap_or_else(|| word.to_string())
    }

}

